//! 🫴️ Original semantic recipients preserve every admitted SQL and DSL birth across refusals.
use super::*;
use store::{ArtifactSqliteSnapshot as _,ArtifactDsl as _};
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,RetainedCloneGrant,RetainedCloneProgress};
use std::cell::Cell;
fn contract()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn cases()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap()}
fn grant(value:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:value["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:value["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["maximumDepth"].as_u64().unwrap()as usize}}
fn database(rows:&serde_json::Value)->SqliteDatabase{SqliteDatabase{tables:vec![store::sqlite_snapshot::SqliteTable{name:"probe_node".to_string(),sql:super::super::ProbeSnapshot::SQLITE_SCHEMA.trim().trim_end_matches(';').to_string(),rows:rows.as_array().unwrap().iter().map(|row|SqliteRow{rowid:row[0].as_i64().unwrap(),values:row.as_array().unwrap().iter().map(|cell|if cell.is_null(){SqliteValue::Null}else if let Some(integer)=cell.as_i64(){SqliteValue::Integer(integer)}else{SqliteValue::Text(cell.as_str().unwrap().to_string())}).collect()}).collect()}]}}
fn same_rows(database:&SqliteDatabase,rows:&serde_json::Value){let actual=database.tables[0].rows.iter().map(|row|row.values.iter().map(|cell|match cell{SqliteValue::Null=>serde_json::Value::Null,SqliteValue::Integer(value)=>serde_json::json!(value),SqliteValue::Text(value)=>serde_json::json!(value),_=>panic!("Probe declared scalar")}).collect::<Vec<_>>()).collect::<Vec<_>>();assert_eq!(serde_json::json!(actual),*rows);}
fn close_decode(native:&mut NativeDecodeControl<'_>,law:&serde_json::Value){let before=native.owned_bytes();let held=native.has_retirement_owner();let denied=native.close_retirement_recipient(grant(&law["deniedCloseGrant"])).unwrap();assert_eq!(denied.progress(),RetainedCloneProgress::default());assert_eq!(native.owned_bytes(),before);assert_eq!(native.has_retirement_owner(),held);let closing=grant(&law["closeGrant"]);for _ in 0..law["maximumCloseTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){return}let step=native.close_retirement_recipient(closing).unwrap();assert!(step.progress().fits(closing));}panic!("Probe semantic decode recipient failed terminal retirement")}
fn close_encode(native:&mut NativeEncodeControl<'_>,law:&serde_json::Value){let before=native.owned_bytes();let held=native.has_retirement_owner();let denied=native.close_retirement_recipient(grant(&law["deniedCloseGrant"])).unwrap();assert_eq!(denied.progress(),RetainedCloneProgress::default());assert_eq!(native.owned_bytes(),before);assert_eq!(native.has_retirement_owner(),held);let closing=grant(&law["closeGrant"]);for _ in 0..law["maximumCloseTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){return}let step=native.close_retirement_recipient(closing).unwrap();assert!(step.progress().fits(closing));}panic!("Probe semantic encode recipient failed terminal retirement")}

#[test]
fn probe_sqlite_original_semantic_receiving_preserves_neutral_rows_and_source_ordinals(){
 let law=contract();let fixture=cases();let incoming=grant(&law["bodyGrant"]);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;
 for sample in fixture["cases"].as_array().unwrap(){
  let original=super::super::ProbeSnapshot::parse_dsl(sample["wire"].as_str().unwrap()).unwrap();let oracle:serde_json::Value=serde_json::from_str(sample["wire"].as_str().unwrap()).unwrap();
  let mut accepted=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeDecodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotDecodeOwner::new(&mut native,incoming);
  let output=original.to_sqlite_database_receiving(&mut control,&mut owner).unwrap();same_rows(&output,&sample["rows"]);assert!(owner.progress().fits(incoming));assert!(owner.progress().retained_capacity_bytes>0);assert!(owner.progress().released_bytes>0);drop(owner);assert!(!native.has_retirement_owner());assert_eq!(control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),native.owned_bytes());
  let mut input=database(&sample["rows"]);if sample==&fixture["cases"][0]{let rows=&mut input.tables[0].rows;rows.sort_by_key(|row|fixture["semanticEdges"]["physicalOrder"].as_array().unwrap().iter().position(|id|id.as_i64()==Some(row.rowid)).unwrap());}else{input.tables[0].rows.reverse();}
  let source=input.tables[0].rows.as_ptr();let mut accepted=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeEncodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotEncodeOwner::new(&mut native,incoming);
  let rebuilt=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap();assert_eq!(rebuilt,original);assert_eq!(serde_json::Value::from(rebuilt.0),oracle);assert_eq!(input.tables[0].rows.as_ptr(),source);assert!(owner.progress().fits(incoming));assert!(owner.progress().retained_capacity_bytes>0);assert!(owner.progress().released_bytes>0);drop(owner);assert!(!native.has_retirement_owner());assert_eq!(control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),native.owned_bytes());
 }
 eprintln!("[DEBUG] Original Probe receiving frames publish genuine SQL rows and DSL trees, preserve shuffled physical source ordinals and match independent Serde semantics with exact cumulative allocation receipts");
}

#[test]
fn probe_sqlite_original_semantic_refused_grants_keep_original_recipient(){
 let law=contract();let fixture=cases();let full=grant(&law["bodyGrant"]);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;let sample=&fixture["cases"][0];let source=super::super::ProbeSnapshot::parse_dsl(sample["wire"].as_str().unwrap()).unwrap();let input=database(&sample["rows"]);
 for row in law["refusals"].as_array().unwrap(){let mut incoming=full;let value=row["value"].as_u64().unwrap()as usize;match row["axis"].as_str().unwrap(){"work"=>incoming.maximum_items=value,"copy"=>incoming.maximum_copy_bytes=value,"capacity"=>incoming.maximum_capacity_bytes=value,"release"=>incoming.maximum_release_bytes=value,"depth"=>incoming.maximum_depth=value,_=>unreachable!()}
  let mut accepted=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeDecodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotDecodeOwner::new(&mut native,incoming);let error=source.to_sqlite_database_receiving(&mut control,&mut owner).unwrap_err();assert_eq!(error.kind.as_str(),row["kind"].as_str().unwrap());assert_eq!(error.retained_progress(),owner.progress());assert!(owner.progress().fits(incoming));drop(owner);assert_eq!(control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),native.owned_bytes());close_decode(&mut native,&law);
  let mut accepted=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeEncodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotEncodeOwner::new(&mut native,incoming);let error=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap_err();assert_eq!(error.kind.as_str(),row["kind"].as_str().unwrap());assert_eq!(error.retained_progress(),owner.progress());assert!(owner.progress().fits(incoming));drop(owner);assert_eq!(control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),native.owned_bytes());close_encode(&mut native,&law);
 }
 eprintln!("[DEBUG] Original Probe SQL receiving obeys independent five-axis grants in both directions and retains all refused backing under the original denied-close recipient");
}

#[test]
fn probe_sqlite_original_semantic_every_checkpoint_retains_canceled_partials(){
 let law=contract();let fixture=cases();let incoming=grant(&law["bodyGrant"]);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;let names=fixture["semanticEdges"]["longCommonNames"].as_array().unwrap();let text=law["maximumCancellationCheckpoints"].as_u64().unwrap()as usize;
 let source=super::super::ProbeSnapshot(DslValue::Object(vec![(names[0].as_str().unwrap().to_string(),DslValue::Object(vec![("nested".to_string(),DslValue::String(law["stringUnit"].as_str().unwrap().repeat(law["stringRepetitions"].as_u64().unwrap()as usize)))])),(names[1].as_str().unwrap().to_string(),DslValue::Number(Number::UInt(u64::MAX)))]));
 let mut accepted=|_|true;let mut direct=SqliteSnapshotControl::new(&mut accepted,Default::default());let input=source.to_sqlite_database(&mut direct).unwrap();let source_rows=input.tables[0].rows.as_ptr();let decode_calls=Cell::new(0usize);let encode_calls=Cell::new(0usize);let decode_prefix=Cell::new(false);let encode_prefix=Cell::new(false);let string_bytes=law["stringBytes"].as_u64().unwrap()as usize;
 for stop in 0..=text{
  let mut accepted=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeDecodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let calls=Cell::new(0usize);let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.total==string_bytes&&event.completed>0&&event.completed<string_bytes{decode_prefix.set(true)}calls.set(calls.get()+1);stop==0||calls.get()<stop};let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotDecodeOwner::new(&mut native,incoming);
  if stop>0&&stop<=decode_calls.get(){let error=source.to_sqlite_database_receiving(&mut control,&mut owner).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.retained_progress(),owner.progress());assert!(owner.progress().fits(incoming));drop(owner);assert!(native.has_retirement_owner());assert_eq!(control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),native.owned_bytes());close_decode(&mut native,&law);}else if stop==0{source.to_sqlite_database_receiving(&mut control,&mut owner).unwrap();decode_calls.set(calls.get());assert!(decode_calls.get()<text);drop(owner);}else{drop(owner);}
  let mut accepted=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeEncodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let calls=Cell::new(0usize);let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.total==string_bytes&&event.completed>0&&event.completed<string_bytes{encode_prefix.set(true)}calls.set(calls.get()+1);stop==0||calls.get()<stop};let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotEncodeOwner::new(&mut native,incoming);
  if stop>0&&stop<=encode_calls.get(){let error=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.retained_progress(),owner.progress());assert!(owner.progress().fits(incoming));drop(owner);assert!(native.has_retirement_owner());assert_eq!(control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),native.owned_bytes());close_encode(&mut native,&law);}else if stop==0{super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap();encode_calls.set(calls.get());assert!(encode_calls.get()<text);drop(owner);}else{drop(owner);}
  assert_eq!(input.tables[0].rows.as_ptr(),source_rows);if stop>=decode_calls.get().max(encode_calls.get())&&stop!=0{break}
 }
 assert!(decode_prefix.get());assert!(encode_prefix.get());
 eprintln!("[DEBUG] Original Probe semantic cancellation exhaustively reached every SQL and DSL checkpoint: projection={} reconstruction={}, retaining database, row, cell, partial strings, parent/index/group/name/consumption buffers and nested DSL birth until funded terminal",decode_calls.get(),encode_calls.get());
}

#[test]
fn probe_sqlite_original_semantic_exact_numeric_words_and_original_ceilings(){
 let law=contract();let fixture=cases();let incoming=grant(&law["bodyGrant"]);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;
 for word in fixture["semanticEdges"]["numericWords"].as_array().unwrap(){let text=word["text"].as_str().unwrap();let input=database(&serde_json::json!([[1,null,null,null,"number",null,text,null]]));let oracle=super::super::ProbeSnapshot::parse_dsl(text).unwrap().0;for limit in [text.len()-1,text.len()]{let mut accepted=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeEncodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,store::sqlite_snapshot::SqliteDatabaseLimits{max_value_bytes:limit,..Default::default()});let mut owner=store::NativeSnapshotEncodeOwner::new(&mut native,incoming);let result=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner);if limit==text.len(){let value=result.unwrap().0;assert_eq!(value,oracle);match(value,word["exactKind"].as_str().unwrap()){(DslValue::Number(Number::UInt(_)),"uint")|(DslValue::Number(Number::Int(_)),"int")=>{},(DslValue::Number(Number::Float(value)),"float")=>if text=="-0.0"{assert!(value.is_sign_negative());assert_eq!(value,0.0)},_=>panic!("exact numeric kind")}}else{let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(error.retained_progress(),owner.progress());}drop(owner);assert_eq!(control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),native.owned_bytes());close_encode(&mut native,&law);}}
 for word in law["invalidNumberWords"].as_array().unwrap(){let input=database(&serde_json::json!([[1,null,null,null,"number",null,word,null]]));let mut accepted=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeEncodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotEncodeOwner::new(&mut native,incoming);let error=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.retained_progress(),owner.progress());drop(owner);close_encode(&mut native,&law);}
 eprintln!("[DEBUG] Original Probe numeric TEXT uses the first-party scalar cursor, preserves UInt/Int/negative-zero Float, rejects nonexact words and enforces the independent exact value byte ceiling before scan");
}

#[test]
fn probe_sqlite_original_semantic_zero_allocation_refuses_before_birth(){
 let law=contract();let fixture=cases();let incoming=grant(&law["bodyGrant"]);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;let source=super::super::ProbeSnapshot::parse_dsl(fixture["cases"][0]["wire"].as_str().unwrap()).unwrap();let input=database(&fixture["cases"][0]["rows"]);let limits=store::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:0,..Default::default()};
 let mut accepted=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|{ledger.fetch_add(request.bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeDecodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,limits);let mut owner=store::NativeSnapshotDecodeOwner::new(&mut native,incoming);let error=source.to_sqlite_database_receiving(&mut control,&mut owner).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(owner.progress(),Default::default());drop(owner);assert_eq!(native.owned_bytes(),0);assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),0);assert!(!native.has_retirement_owner());
 let mut accepted=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{ledger.fetch_add(request.bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut native=NativeEncodeControl::new_forwarded(maximum,&mut accepted,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,limits);let mut owner=store::NativeSnapshotEncodeOwner::new(&mut native,incoming);let error=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(owner.progress(),Default::default());drop(owner);assert_eq!(native.owned_bytes(),0);assert_eq!(ledger.load(std::sync::atomic::Ordering::Relaxed),0);assert!(!native.has_retirement_owner());
 eprintln!("[DEBUG] Original Probe zero SQL allocation ceilings refuse both receiving directions before any native frame or allocator birth");
}

#[test]
fn probe_sqlite_original_semantic_secondary_refusals_keep_cumulative_original_receipts(){
 let law=contract();let fixture=cases();let incoming=grant(&law["bodyGrant"]);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;let sample=&fixture["cases"][0];let source=super::super::ProbeSnapshot::parse_dsl(sample["wire"].as_str().unwrap()).unwrap();let input=database(&sample["rows"]);
 let mut accepted=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(maximum,&mut accepted);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotDecodeOwner::new(&mut native,incoming);let output=source.to_sqlite_database_receiving(&mut control,&mut owner).unwrap();let prior=owner.progress();assert!(prior.copied_items>0);control.restrict_limits(store::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),..control.limits()}).unwrap();let error=source.to_sqlite_database_receiving(&mut control,&mut owner).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(error.retained_progress(),prior);assert_eq!(owner.progress(),prior);same_rows(&output,&sample["rows"]);drop(owner);assert!(!native.has_retirement_owner());
 let mut accepted=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut native=NativeEncodeControl::new(maximum,&mut accepted);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let mut owner=store::NativeSnapshotEncodeOwner::new(&mut native,incoming);let output=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap();let prior=owner.progress();assert!(prior.copied_items>0);control.restrict_limits(store::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:control.limits().max_allocation_bytes-control.allocation_remaining_bytes(),..control.limits()}).unwrap();let error=super::super::ProbeSnapshot::from_sqlite_database_receiving(&input,&mut control,&mut owner).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(error.retained_progress(),prior);assert_eq!(owner.progress(),prior);assert_eq!(output,source);drop(owner);assert!(!native.has_retirement_owner());
 eprintln!("[DEBUG] Original Probe semantic secondary ceiling refusals preserve genuine previously published output and the same original cumulative producer receipts without a new allocator birth");
}
